import heapq
def main():
    n, m = map(int, input().split()); adj = [[] for _ in range(n + 1)]; ind = [0] * (n + 1)
    for _ in range(m):
        a, b = map(int, input().split()); adj[a].append(b); ind[b] += 1
    h = [i for i in range(1, n + 1) if ind[i] == 0]; heapq.heapify(h); r = []
    while h:
        u = heapq.heappop(h); r.append(u)
        for v in adj[u]:
            ind[v] -= 1
            if ind[v] == 0: heapq.heappush(h, v)
    print(*r)

